import {moreGuides} from './extended-guides.ts';
import {deepGuides} from './deep-guides.ts';
export type Guide={id:string;topic:'HTML'|'CSS'|'Workflow';title:string;summary:string;meaning:string;where:string;steps:string[];pitfalls:string[];html:string;css:string;sources:string[]};
const base='body { font-family: system-ui, sans-serif; line-height: 1.65; padding: 24px; color: #223d32; }';
export const guides:Guide[]=[
{id:'start',topic:'HTML',title:'HTML, CSS, and your first complete page',summary:'Understand the two languages, the files they live in, and how a browser combines them.',meaning:'HTML (HyperText Markup Language) describes the structure and meaning of a document. CSS (Cascading Style Sheets) describes its presentation. Neither replaces JavaScript for general program logic. Browsers parse HTML into a document tree, collect applicable CSS, resolve competing declarations, then lay out and paint the result.',where:'Use HTML for web pages, document content, forms, navigation, and accessible structure. Use CSS for screen layouts, typography, print styles, responsive components, and visual states. On GitHub Pages, publish the resulting HTML/CSS/JavaScript files; server code needs a separate host.',steps:['Create index.html and styles.css in the same folder. The HTML file is the page entry point.','Start with <!doctype html> so the document uses standards mode. Set lang to the content’s language.','Put the character encoding, viewport metadata, title, and stylesheet link in <head>.','Put visible page content inside <body>. Save both files and open index.html or use a local development server.','The stylesheet link resolves relative to the HTML document. The playground combines the HTML and CSS editor panes for you.'],pitfalls:['A .css file contains CSS rules, not <style> tags. A .html file contains markup.','A browser preview is not a server. A form does not store messages unless a real endpoint handles submissions.'],html:'<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>My first page</title>\n  <link rel="stylesheet" href="styles.css">\n</head>\n<body>\n  <main class="welcome">\n    <h1>I built this.</h1>\n    <p>One page. Endless possibilities.</p>\n  </main>\n</body>\n</html>',css:base+'\n.welcome { max-width: 40rem; margin-inline: auto; padding: 2rem; background: #edf4df; border-radius: 1rem; }',sources:['https://html.spec.whatwg.org/multipage/syntax.html','https://www.w3.org/TR/css-2026/','https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages']},
{id:'html-anatomy',topic:'HTML',title:'Elements, tags, attributes, and nesting',summary:'Read the parts of a line of HTML and build a valid document tree.',meaning:'A tag is markup such as <p> or </p>. An element includes its tags and its content in the document model. Attributes configure an element; a class groups elements for CSS and scripting, while an id identifies one element in a document. Child elements are nested inside parent elements. Void elements, such as img and input, do not have end tags.',where:'Use these rules everywhere you write HTML, including full pages, component templates, CMS content, and server-rendered documents.',steps:['Write an opening tag such as <article class="note">. The name identifies the element and class is an attribute.','Place text and permitted child elements inside it. Close nested elements in the reverse order you opened them.','Quote attribute values to avoid accidental parsing changes when values contain spaces or special characters.','Use <!-- ... --> for a comment. Comments are not displayed as page content.','Consult an element’s permitted content and parent rules; arbitrary nesting is not always valid.'],pitfalls:['Do not put a <div> or heading inside a <p>; the HTML parser may close the paragraph automatically.','Boolean HTML attributes are true by their presence. disabled="false" still disables a control. Remove the attribute to make it false.'],html:'<article class="note" id="first-note">\n  <!-- A heading and paragraph are children of article. -->\n  <h1>A small introduction</h1>\n  <p>I am learning <strong>HTML</strong>.</p>\n  <input type="checkbox" id="agree" checked>\n  <label for="agree">I am ready to build.</label>\n</article>',css:base+'\n.note { border: 1px solid #cbd7bd; padding: 24px; border-radius: 12px; }\nstrong { color: #3d6e40; }',sources:['https://html.spec.whatwg.org/multipage/syntax.html','https://html.spec.whatwg.org/multipage/common-microsyntaxes.html#boolean-attributes']},
{id:'semantics',topic:'HTML',title:'Semantic landmarks and headings',summary:'Give a page a structure that people and assistive tools can navigate.',meaning:'Semantic HTML describes the role of content rather than its appearance. main identifies the document’s dominant content. nav groups major navigation. article is a self-contained composition; section groups thematic content, usually with a heading. header and footer belong to a page or section. A div is a generic container without this extra meaning.',where:'Apply landmarks to page shells, documentation, articles, dashboards, and content-heavy interfaces. Choose headings by document hierarchy, not by the size you want.',steps:['Use one visible main landmark for the page’s primary content.','Put major navigation links inside nav and provide an accessible label when multiple nav elements need distinction.','Use h1 for the page’s main heading, then h2 and h3 for nested sections.','Choose article only when the content makes sense independently. Use section for a thematic group.','Style these elements with CSS; semantic elements do not automatically create the layout you want.'],pitfalls:['A section is not a substitute for every layout wrapper. Use div when no semantic element fits.','Do not simulate headings using a bold paragraph. Screen-reader heading navigation depends on actual headings.'],html:'<header><a href="#">Little studio</a></header>\n<nav aria-label="Main"><a href="#work">Our work</a></nav>\n<main>\n  <h1>Built with curiosity</h1>\n  <section id="work">\n    <h2>Our latest work</h2>\n    <article><h3>A garden journal</h3><p>A project for growing ideas.</p></article>\n  </section>\n</main>\n<footer><small>Made by our studio.</small></footer>',css:base+'\nheader, footer { padding-block: 1rem; }\nnav a { margin-inline-end: 1rem; }\narticle { background: #edf4df; padding: 1rem; border-radius: 10px; }',sources:['https://html.spec.whatwg.org/multipage/sections.html','https://html.spec.whatwg.org/multipage/grouping-content.html#the-main-element']},
{id:'text',topic:'HTML',title:'Text, emphasis, lists, and character references',summary:'Mark up writing according to its meaning, including special characters.',meaning:'p represents a paragraph. em gives stress emphasis, and strong marks strong importance. code marks computer code; pre preserves whitespace. ul is an unordered list, ol is an ordered list, and li is a list item. dl groups terms and descriptions with dt and dd. Character references represent characters that would otherwise be parsed as markup or are inconvenient to type.',where:'Use text semantics in documentation, articles, instructions, product descriptions, and code tutorials. Use ordered lists when sequence matters.',steps:['Separate paragraphs with p elements rather than repeated line breaks.','Use em and strong for meaning. Use CSS for purely visual italics or bold.','Use pre together with code to show multiline code while preserving spaces.','Write &lt; for <, &gt; for >, and &amp; for & when showing markup as text.','Place li inside ul or ol, and dt/dd pairs inside dl.'],pitfalls:['br is for meaningful line breaks, such as an address or poem; it is not a spacing tool.','HTML normally collapses repeated whitespace outside whitespace-preserving contexts.'],html:'<h1>A tiny recipe</h1>\n<p><strong>Remember:</strong> start with <em>curiosity</em>.</p>\n<ol><li>Write HTML.</li><li>Add CSS.</li><li>Try again.</li></ol>\n<dl><dt>HTML</dt><dd>Structure and meaning.</dd></dl>\n<pre><code>&lt;p&gt;Hello &amp; welcome.&lt;/p&gt;</code></pre>',css:base+'\npre { padding: 1rem; background: #edf4df; overflow: auto; }\ndt { font-weight: 700; }',sources:['https://html.spec.whatwg.org/multipage/text-level-semantics.html','https://html.spec.whatwg.org/multipage/grouping-content.html','https://html.spec.whatwg.org/multipage/named-characters.html']},
{id:'links',topic:'HTML',title:'Links, URLs, and navigation',summary:'Know the difference between going somewhere and doing something.',meaning:'An a element with href creates a hyperlink. Absolute URLs specify a full destination; relative URLs resolve against the document’s base URL. A fragment such as #contact points to an element with that id. A button performs an action. The distinction gives users appropriate keyboard behavior and accessible semantics.',where:'Use links for navigation, downloadable resources, email links, and in-page tables of contents. Use buttons for opening a menu, submitting a form, checking an answer, or changing application state.',steps:['Put a meaningful destination in href. Write link text that describes the destination.','For same-page navigation, add an id to the target and link to # followed by that id.','For a relative destination, account for the current directory, especially a GitHub Pages project subdirectory.','Use target="_blank" only when a new browsing context is appropriate; rel="noopener" makes the intended isolation explicit.','Use a button with type="button" for an action that should not submit a surrounding form.'],pitfalls:['Do not use href="#" as a replacement for a real action button.','Root-relative /assets/... links point to the domain root, not automatically your GitHub repository subdirectory.'],html:'<nav aria-label="Page sections">\n  <a href="#contact">Contact the studio</a>\n  <a href="https://html.spec.whatwg.org/" target="_blank" rel="noopener">Read the HTML standard</a>\n</nav>\n<section id="contact"><h1>Let’s talk.</h1><a href="mailto:hello@example.com">Email the studio</a></section>',css:base+'\na { color: #346b42; text-underline-offset: .2em; }\na:focus-visible { outline: 3px solid #376cbe; outline-offset: 4px; }',sources:['https://html.spec.whatwg.org/multipage/links.html','https://html.spec.whatwg.org/multipage/urls-and-fetching.html']},
{id:'images',topic:'HTML',title:'Images, alternative text, and responsive sources',summary:'Display an image without leaving accessibility or layout stability behind.',meaning:'img embeds an image from src. alt provides a text replacement based on the image’s purpose. Width and height attributes establish intrinsic dimensions and can help reserve layout space. srcset offers image candidates and sizes describes the expected display width for width-descriptor candidates. picture selects among source alternatives for art direction or formats.',where:'Use images in content, galleries, cards, and editorial pages. Prefer CSS backgrounds for purely decorative styling that does not require content semantics.',steps:['Give a meaningful image a concise alternative describing the information it conveys. Use alt="" for a purely decorative image.','Set width and height according to the image’s intrinsic aspect ratio. Let CSS scale it responsively.','Use max-width:100% and height:auto to fit a container while preserving the aspect ratio.','Use srcset and sizes when multiple resolutions of the same image are available.','Use figure and figcaption for an image with a self-contained caption.'],pitfalls:['The alt text should not merely repeat “image of” when the content can be described directly.','Only list image candidates that actually exist. A source declaration does not generate image files.'],html:'<figure>\n  <img src="plant.svg" alt="A green plant in a terracotta pot" width="200" height="220">\n  <figcaption>A little room to grow.</figcaption>\n</figure>',css:base+'\nfigure { margin: 0; max-width: 320px; }\nimg { max-width: 100%; height: auto; }\nfigcaption { color: #667761; font-size: .875rem; }',sources:['https://html.spec.whatwg.org/multipage/images.html','https://html.spec.whatwg.org/multipage/embedded-content.html#the-img-element']},
{id:'tables',topic:'HTML',title:'Accessible data tables',summary:'Represent relationships between row and column values.',meaning:'A table is for tabular data. caption names the table, thead groups heading rows, tbody groups body rows, tr defines a row, th identifies a header cell, and td identifies a data cell. scope="col" and scope="row" explicitly identify simple column and row header relationships.',where:'Use tables for schedules, comparison data, grade lists, and other information with meaningful row/column relationships. Use Grid or Flexbox for visual page layout.',steps:['Give the table a caption that describes its purpose.','Build each row with tr and place headers in th rather than making ordinary cells bold.','Use scope on simple headers to express the header direction.','Keep the number and arrangement of cells consistent; complex spanning tables may require explicit headers/id associations.','Wrap a wide table in an overflow container so it can scroll on narrow screens.'],pitfalls:['Do not use a table only to position a sidebar or navigation.','Do not remove header semantics for a purely visual mobile redesign.'],html:'<div class="table-scroll">\n<table>\n  <caption>A week of little wins</caption>\n  <thead><tr><th scope="col">Day</th><th scope="col">Practice</th></tr></thead>\n  <tbody>\n    <tr><th scope="row">Monday</th><td>HTML structure</td></tr>\n    <tr><th scope="row">Tuesday</th><td>CSS layouts</td></tr>\n  </tbody>\n</table>\n</div>',css:base+'\n.table-scroll { overflow-x: auto; }\ntable { border-collapse: collapse; width: 100%; }\ncaption { text-align: start; font-weight: 700; margin-bottom: 1rem; }\nth, td { border: 1px solid #d4ddc8; padding: .75rem; text-align: start; }',sources:['https://html.spec.whatwg.org/multipage/tables.html']},
{id:'forms',topic:'HTML',title:'Forms, labels, names, and validation',summary:'Understand what an HTML form can do and what needs a server.',meaning:'A form groups controls for submission. action names the destination URL and method chooses how form data is sent. A label provides a control’s accessible name. The id connects an explicit label, while name is the key used in submitted data. Browser validation helps users correct input, but server-side validation remains necessary for data security and correctness.',where:'Use forms for sign-up, search, contact information, settings, and other structured user input. In this playground, forms are sandboxed examples and do not send or store data.',steps:['Give every relevant control a visible label. Match label for to the control’s unique id.','Choose the appropriate input type and add a name so the control can contribute to form data.','Use required, minlength, maxlength, min, max, step, or pattern when their constraints match the control type.','Use fieldset and legend to group related controls, such as a set of radio options.','Choose a real server endpoint for production submissions; validate all fields again on that server.'],pitfalls:['A placeholder is not a replacement for a label.','Disabled controls are generally excluded from form submission. readonly and disabled have different meanings.','Client-side validation does not establish that an email address exists or that a user is authorized.'],html:'<form action="/subscribe" method="post">\n  <h1>Stay in the loop.</h1>\n  <label for="email">Email address</label>\n  <input id="email" name="email" type="email" autocomplete="email" required>\n  <fieldset>\n    <legend>What do you want to learn?</legend>\n    <label><input type="checkbox" name="topic" value="html"> HTML</label>\n    <label><input type="checkbox" name="topic" value="css"> CSS</label>\n  </fieldset>\n  <button type="submit">Subscribe</button>\n</form>',css:base+'\nform { max-width: 28rem; }\nlabel, input[type="email"] { display: block; margin-block: .5rem; }\ninput[type="email"], button { padding: .75rem; }\nfieldset { border: 1px solid #ccd8bb; margin-block: 1rem; }',sources:['https://html.spec.whatwg.org/multipage/forms.html','https://html.spec.whatwg.org/multipage/form-control-infrastructure.html']},
{id:'input-types',topic:'HTML',title:'Input types and control choices',summary:'Select controls according to the data they represent.',meaning:'The input type attribute selects a control state. Common types include text, search, email, url, tel, password, number, range, date, time, datetime-local, month, week, color, checkbox, radio, file, hidden, submit, reset, button, and image. Behavior, applicable attributes, and browser UI differ by state. textarea is for multiline plain text; select presents options.',where:'Use these controls in accessible forms. A telephone number is not a quantity to increment; type="tel" is usually more appropriate than type="number" for it.',steps:['Choose type for data semantics rather than only for the keyboard it happens to show.','Use a shared name on radio buttons for a mutually exclusive choice. Use distinct values for the options.','Use checked to set an initial checkbox or radio state. Use selected on an option for an initial select choice.','Use textarea for multiple lines and select/option for a predefined choice list.','Use inputmode as a keyboard hint when appropriate; it does not enforce validation by itself.'],pitfalls:['Not every browser displays date, time, month, and week controls identically. Check the compatibility record for each state.','accept on a file input is a selection hint, not a security validation of the uploaded file.'],html:'<form>\n<label for="experience">Experience</label>\n<select name="experience" id="experience"><option value="new">New to coding</option><option value="some">A little experience</option></select>\n<fieldset><legend>Preferred language</legend>\n<label><input type="radio" name="language" value="html" checked> HTML</label>\n<label><input type="radio" name="language" value="css"> CSS</label></fieldset>\n<label for="idea">Your idea</label>\n<textarea id="idea" name="idea" rows="4"></textarea>\n</form>',css:base+'\nselect, textarea { display: block; padding: .75rem; width: 100%; max-width: 28rem; }\nfieldset { border: 1px solid #ccd8bb; margin-block: 1rem; }',sources:['https://html.spec.whatwg.org/multipage/input.html','https://html.spec.whatwg.org/multipage/form-elements.html']},
{id:'media',topic:'HTML',title:'Media, embeds, and built-in disclosure',summary:'Know the requirements and limits of embedded content.',meaning:'audio and video provide native media playback controls. source offers alternative resources and track supplies timed text such as captions. iframe creates a nested browsing context and sandbox can restrict its capabilities. details and summary provide a built-in disclosure widget without a JavaScript library.',where:'Use media elements for actual audio/video assets, iframe for intentionally embedded documents, and details for optional supporting information. This learning site runs code in a sandboxed iframe with scripts and form submissions disabled.',steps:['Provide controls on media when users need to choose playback. Include captions for meaningful spoken video content.','Use actual media resources with correct MIME types; a source element is not the media file itself.','Give an iframe a descriptive title. Grant only the sandbox capabilities its content genuinely needs.','For a native disclosure, place summary as the first child of details.','Use the open boolean attribute if a disclosure should start expanded.'],pitfalls:['Autoplay can be blocked by browsers and can be disruptive.','A sandbox that allows both scripts and same-origin behavior for same-origin content can defeat important isolation expectations.','The sample below demonstrates disclosure without relying on external media or scripts.'],html:'<details>\n  <summary>How does the live preview work?</summary>\n  <p>Your HTML and CSS are rendered inside a sandboxed iframe.</p>\n  <p>Scripts, pop-ups, and form submissions are not enabled here.</p>\n</details>',css:base+'\ndetails { padding: 1rem; border: 1px solid #cbd7bf; border-radius: 12px; }\nsummary { cursor: pointer; font-weight: 700; }\ndetails[open] summary { margin-bottom: 1rem; }',sources:['https://html.spec.whatwg.org/multipage/media.html','https://html.spec.whatwg.org/multipage/iframe-embed-object.html','https://html.spec.whatwg.org/multipage/interactive-elements.html']},
{id:'css-attachment',topic:'CSS',title:'Selectors, declarations, and stylesheet placement',summary:'Connect CSS to HTML and understand the anatomy of a rule.',meaning:'A style rule selects elements and applies a declaration block. Each declaration pairs a property with a value using a colon and usually ends with a semicolon. External stylesheets are linked from head. An internal stylesheet is placed in a style element. Inline declarations live in an element’s style attribute.',where:'Use external CSS for reusable website styles. Internal CSS can make a single-page example self-contained. Inline declarations can suit narrowly generated values, but are harder to maintain and have special cascade precedence.',steps:['Choose a selector: p selects all paragraphs; .card selects elements whose class list contains card; #intro selects an element with that id.','Put property:value declarations between braces.','Link an external stylesheet with <link rel="stylesheet" href="styles.css">.','For an internal stylesheet, place ordinary CSS rules inside <style> in the head.','Inspect the browser’s computed styles when a declaration does not seem to apply. Check spelling, loading, selector matching, and competing rules.'],pitfalls:['HTML class="card" is selected by .card, including the dot; class itself does not include the dot.','A CSS comment is /* ... */. HTML comments are not a general replacement inside stylesheets.'],html:'<article class="card" id="intro">\n  <h1>Structure meets style.</h1>\n  <p>A reusable class connects this markup to CSS.</p>\n</article>',css:base+'\n/* Select the card class. */\n.card {\n  background-color: #e8f2dc;\n  padding: 24px;\n  border-radius: 12px;\n}\n.card h1 { margin-top: 0; }',sources:['https://www.w3.org/TR/css-syntax-3/','https://html.spec.whatwg.org/multipage/semantics.html#the-link-element']},
{id:'cascade',topic:'CSS',title:'Cascade, inheritance, specificity, and layers',summary:'Work out why one declaration wins over another.',meaning:'The cascade resolves competing declarations. Origin, importance, and cascade layer precedence are considered before selector specificity. When relevant competing declarations still tie, scoping proximity and order of appearance can resolve the result. Inheritance passes some property values from parent to child; it does not apply automatically to every property. Specificity counts IDs, class-like selectors, and type-like selectors in separate columns.',where:'Use this model to debug component overrides, third-party styles, themes, and design systems. Layers let you establish predictable ordering without escalating selector weight.',steps:['First check whether the declaration is relevant and the selector matches.','Check origin and importance, then layer order. For normal author declarations, later layers outrank earlier ones, and unlayered rules outrank layered rules.','Within the applicable precedence level, compare specificity. IDs outweigh classes/attributes/pseudo-classes, which outweigh element types/pseudo-elements.','For important declarations, layer order is reversed. !important is not a specificity score.','Use inherit, initial, unset, revert, and revert-layer deliberately; they perform different kinds of defaulting.'],pitfalls:['“Last rule always wins” is false. Order matters only after the earlier cascade comparisons tie.','Normal inline styles outrank normal author stylesheet rules, but not every possible declaration or running transition.'],html:'<p class="message">The component layer wins this normal declaration.</p>',css:'@layer base, components;\n@layer base { .message { color: #96603c; } }\n@layer components { .message { color: #2f6941; } }\nbody { font-family: system-ui; padding: 24px; }',sources:['https://www.w3.org/TR/css-cascade-5/','https://www.w3.org/TR/selectors-4/#specificity-rules','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Cascade/Introduction']},
{id:'grammar',topic:'CSS',title:'How to read formal CSS syntax',summary:'Decode every value grammar in the reference.',meaning:'Formal syntax is a grammar, not code to paste into a stylesheet. Angle brackets name a data type or another production. Keywords are literal tokens. A single bar means choose one alternative; a double bar allows one or more alternatives in any order; a double ampersand requires all parts in any order. Juxtaposition normally requires the written sequence.',where:'Use formal grammar on property, function, descriptor, and at-rule reference entries when you need the complete accepted structure rather than just a short example list.',steps:['Read <length> as a length value such as 12px, not as literal angle-bracket text. <color> names a color value type.','Read [ ... ] as grouping. A ? makes a part optional; * allows zero or more repetitions; + requires one or more.','Read # as a comma-separated repetition and {m,n} as a repetition count range.','Use the context: / can be a literal separator, while |, ||, and && are grammar combinators.','A grammar can accept arbitrarily many numerical values, strings, and combinations. The grammar is the finite description of that unbounded space.'],pitfalls:['Do not paste <length> or [ red | blue ] as a property value. Replace productions with an actual valid value.','A value in a specification grammar can still lack browser implementation. Check compatibility independently.'],html:'<div class="example">12px and 24px are actual length values.</div>',css:base+'\n/* padding grammar includes <length-percentage>{1,4}. */\n.example { padding: 12px 24px; background: #edf4df; }',sources:['https://www.w3.org/TR/css-values-4/#value-defs','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Values_and_units']},
{id:'units',topic:'CSS',title:'Values, units, percentages, and calculations',summary:'Understand what CSS numbers are relative to.',meaning:'CSS values have types, including lengths, percentages, numbers, integers, angles, times, resolutions, colors, strings, and identifiers. px is a CSS reference pixel, not necessarily one physical screen pixel. rem is relative to the root font size; em is context-dependent and often relative to the element’s font size. Percentages are resolved according to the property. Viewport units and container units have their own reference dimensions.',where:'Use rem for many typographic and spacing decisions, percentages for proportional dimensions where their basis is understood, fr for Grid free-space shares, and calc/min/max/clamp for constraints.',steps:['Use units that the property’s grammar permits. A nonzero length generally needs a length unit.','Use rem to scale relative to the root text size. For font-size, em is based on the inherited font size.','Use calc() for compatible arithmetic; addition and subtraction operators require surrounding whitespace.','Use clamp(minimum, preferred, maximum) to keep a fluid value within limits.','Choose small/dynamic/large viewport units (svh/dvh/lvh etc.) deliberately on mobile interfaces.'],pitfalls:['A percentage height can depend on whether the containing block has a definite size.','fr is a Grid track flex factor, not a universal substitute for a length in every CSS property.'],html:'<article class="fluid"><h1>Room to grow.</h1><p>This card fits the space available.</p></article>',css:base+'\n.fluid { width: min(100%, 36rem); padding: clamp(1rem, 4vw, 2rem); box-sizing: border-box; background: #edf4df; }\nh1 { font-size: clamp(1.75rem, 5vw, 3rem); line-height: 1.1; }',sources:['https://www.w3.org/TR/css-values-4/','https://www.w3.org/TR/css-grid-2/#fr-unit']},
{id:'selectors',topic:'CSS',title:'Selectors, pseudo-classes, and pseudo-elements',summary:'Target relationships, states, and generated parts.',meaning:'Selectors match elements in a document tree. A space selects descendants, > selects children, + selects the next sibling, and ~ selects subsequent siblings. Attribute selectors match attribute conditions. Pseudo-classes such as :hover, :checked, and :focus-visible match states or structural conditions. Pseudo-elements such as ::before and ::first-letter address generated or selected parts.',where:'Use selectors to style reusable components, interaction states, form validation, list patterns, and document relationships. Keep selectors understandable and prefer semantic HTML over elaborate selector workarounds.',steps:['Use .card > p when only direct child paragraphs should match; .card p also includes deeper descendants.','Use [type="email"] or [aria-expanded="true"] to match an attribute condition.','Use :focus-visible to preserve a visible keyboard focus indicator.','Use :is() and :not() for selector-list conditions; :where() contributes zero specificity.','Use ::before or ::after with content to generate decorative content. Do not put essential information only in generated content.'],pitfalls:[':hover alone is insufficient for touch and keyboard interaction.','Specificity of :is(), :not(), and :has() comes from their arguments; it is not a flat class weight.'],html:'<ul class="ideas"><li>Design</li><li>Code</li><li>Build</li></ul>\n<button type="button">A focusable button</button>',css:base+'\n.ideas > li { margin-block: .5rem; }\n.ideas > li:first-child { font-weight: 700; }\n.ideas > li::marker { color: #79a253; }\nbutton { padding: .75rem 1rem; }\nbutton:is(:hover, :focus-visible) { background: #dff0c3; }\nbutton:focus-visible { outline: 3px solid #659044; outline-offset: 3px; }',sources:['https://www.w3.org/TR/selectors-4/','https://www.w3.org/TR/css-pseudo-4/']},
{id:'box',topic:'CSS',title:'The box model, sizing, and overflow',summary:'Predict the space a component occupies.',meaning:'A CSS box has content, padding, border, and margin areas. Under content-box, width describes the content box. Under border-box, width includes padding and borders. Margin sits outside the border and is not part of that width. Overflow controls what happens when content extends beyond its box.',where:'Apply the box model to cards, buttons, form controls, sidebars, and any sized component. A consistent border-box reset makes many layouts easier to reason about.',steps:['Set box-sizing:border-box on elements and pseudo-elements when that sizing model suits the project.','Use padding for internal breathing room and margin or container gap for external separation.','Use max-width or max-inline-size to avoid unreadably wide content.','Use overflow:auto for content that should scroll when it exceeds its box.','Prefer intrinsic sizing and flexible constraints before assigning fixed heights to text containers.'],pitfalls:['Vertical margins of some block boxes can collapse; padding and gap do not collapse in the same way.','overflow:hidden can hide meaningful content or focus indicators. Use it deliberately.'],html:'<article class="box"><h1>A little breathing room.</h1><p>The border surrounds the padding and content.</p></article>',css:base+'\n*, *::before, *::after { box-sizing: border-box; }\n.box { max-width: 30rem; padding: 24px; border: 2px solid #a6bf80; margin: 16px auto; border-radius: 12px; background: #f0f5e8; }',sources:['https://www.w3.org/TR/css-box-3/','https://www.w3.org/TR/css-sizing-3/','https://www.w3.org/TR/css-overflow-3/']},
{id:'flex',topic:'CSS',title:'Flexbox: layout in one primary direction',summary:'Arrange a row or column of flexible items.',meaning:'display:flex establishes a flex formatting context for direct children. flex-direction chooses the main axis. justify-content distributes space along that axis, while align-items aligns items on the cross axis. flex-wrap allows additional lines. The flex shorthand combines grow, shrink, and basis.',where:'Use Flexbox for navigation bars, button groups, toolbars, aligned form rows, and components whose layout is primarily one-dimensional.',steps:['Set display:flex on the parent, not individually on all children.','Choose row or column, then reason about the main and cross axes.','Use gap for consistent spacing between items.','Use flex-wrap:wrap when items should move to another line.','Set min-width:0 on a flex item when its default minimum size prevents intended shrinking and text truncation.'],pitfalls:['justify-content does not always mean horizontal alignment; the main axis changes with flex-direction.','Visual reordering does not automatically change keyboard or reading order. Keep document order meaningful.'],html:'<nav class="nav" aria-label="Studio">\n  <strong>little studio</strong>\n  <div class="links"><a href="#work">Work</a><a href="#about">About</a></div>\n</nav>',css:base+'\n.nav { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; padding: 1rem; background: #e6f0da; border-radius: 12px; }\n.links { display: flex; gap: 1.25rem; }\na { color: inherit; }',sources:['https://www.w3.org/TR/css-flexbox-1/','https://www.w3.org/TR/css-align-3/']},
{id:'grid',topic:'CSS',title:'Grid: rows and columns that work together',summary:'Build two-dimensional layouts with explicit track rules.',meaning:'display:grid establishes a grid container. grid-template-columns and grid-template-rows define explicit tracks. fr divides available free space. minmax() supplies a size range, repeat() repeats a track pattern, and gap separates tracks. Grid placement can use line numbers, names, or named areas.',where:'Use Grid for card galleries, page shells, aligned dashboards, and content that needs shared rows and columns. Flexbox and Grid can be nested rather than treated as competing choices.',steps:['Define columns on the grid container and let direct children become grid items.','Use repeat(3,1fr) for three equally flexible tracks when intrinsic minimums are suitable.','Use minmax(0,1fr) where a track must be allowed to shrink below its content’s automatic minimum.','Use repeat(auto-fit,minmax(...)) for a responsive number of columns.','Use media or container queries when layout changes need explicit conditions.'],pitfalls:['A grid’s visual placement can differ from document order, affecting reading and keyboard navigation.','A fixed minimum track width can overflow a narrow container; use an appropriate min() constraint or breakpoint.'],html:'<div class="grid">\n  <article>Design</article><article>Develop</article>\n  <article>Discover</article><article>Dream</article>\n</div>',css:base+'\n.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr)); gap: 1rem; }\narticle { padding: 2rem; background: #e6edf8; border-radius: 12px; }',sources:['https://www.w3.org/TR/css-grid-2/']},
{id:'position',topic:'CSS',title:'Positioning and stacking contexts',summary:'Place badges, sticky headers, and overlays without guessing.',meaning:'static uses normal positioning. relative offsets a box while retaining its normal-flow space. absolute removes a box from normal flow and positions it against its containing block. fixed commonly uses the viewport, subject to containing-block rules. sticky combines normal flow with constrained sticking in a scroll container. Stacking contexts organize how z-index values are compared.',where:'Use positioned layout for badges, intentional overlays, sticky navigation, and decorative elements. Use Flexbox/Grid for the primary arrangement of most page content.',steps:['Give the intended containing block position:relative when placing an absolutely positioned child.','Use logical inset properties or top/right/bottom/left for the needed offsets.','For sticky positioning, provide an inset such as top:0 and enough scrolling space.','Remember that transforms, opacity, and other features can create stacking contexts.','Keep overlays reachable, readable, and dismissible when they contain interactive content.'],pitfalls:['z-index:99999 does not escape an ancestor’s stacking context.','Absolutely positioned content does not contribute to normal-flow height.'],html:'<article class="card">\n  <span class="tag">NEW</span>\n  <h1>A fresh idea.</h1><p>The badge is positioned relative to this card.</p>\n</article>',css:base+'\n.card { position: relative; max-width: 28rem; padding: 2rem; background: #edf4df; border-radius: 14px; }\n.tag { position: absolute; top: 12px; right: 12px; padding: .25rem .5rem; background: #d1e7ad; border-radius: 5px; font-size: .75rem; }',sources:['https://www.w3.org/TR/css-position-3/','https://www.w3.org/TR/css-position-4/']},
{id:'type',topic:'CSS',title:'Typography, wrapping, and readable text',summary:'Make content readable before adding decoration.',meaning:'font-family selects a prioritized family list. font-size sets the em square size, font-weight chooses weight, and line-height controls line-box height. Unitless line-height scales with an element’s font size when inherited. text-align, text-decoration, letter-spacing, white-space, overflow-wrap, and word-break affect text presentation and wrapping.',where:'Use typography rules on every content interface. Give documentation and code different font stacks and allow code blocks to scroll rather than clipping them.',steps:['Provide a generic fallback such as sans-serif or monospace after specific font choices.','Choose a comfortable text size and line height; allow users to zoom.','Constrain prose width to keep line lengths manageable.','Use overflow-wrap:anywhere for long unbroken strings that would otherwise overflow a constrained component.','Preserve whitespace in code and use overflow:auto for long lines.'],pitfalls:['Do not disable browser zoom or use tiny text to fit extra content.','A fixed height on paragraphs can clip enlarged text or translated content.'],html:'<article><h1>Clarity is a feature.</h1><p>Readable text gives your ideas room to land. A consistent rhythm helps people follow along.</p><pre><code>.card { padding: 24px; }</code></pre></article>',css:base+'\narticle { max-width: 65ch; margin-inline: auto; }\nh1 { font-size: clamp(2rem, 5vw, 3rem); line-height: 1.15; letter-spacing: -.04em; }\np { font-size: 1.0625rem; line-height: 1.8; }\npre { font-family: ui-monospace, monospace; overflow: auto; padding: 1rem; background: #eef3e6; }',sources:['https://www.w3.org/TR/css-fonts-4/','https://www.w3.org/TR/css-text-3/','https://www.w3.org/TR/css-inline-3/']},
{id:'color',topic:'CSS',title:'Colors, backgrounds, borders, and effects',summary:'Add visual character while keeping content clear.',meaning:'CSS colors can be named keywords, hexadecimal notation, or functions such as rgb(), hsl(), lab(), lch(), oklab(), and oklch(). color affects foreground color; background properties paint behind content. border surrounds the box, border-radius rounds corners, and box-shadow adds a shadow. Gradients are generated images, not just single colors.',where:'Apply these properties to component surfaces, focus indicators, text, borders, and decorative artwork. Browser support for newer color functions and effects must be checked.',steps:['Choose readable text/background combinations and test contrast, including focus and disabled states.','Set a fallback declaration before a newer color or effect when older browser support matters.','Use background-image for a gradient and background-color for a fallback solid surface.','Use border-radius and shadow sparingly to express hierarchy.','Use currentColor when a border or icon should follow the element’s text color.'],pitfalls:['Setting opacity affects the whole element and its descendants; an alpha background color affects only that painted color.','A visual effect does not provide semantic meaning or a text alternative.'],html:'<article class="color-card"><span class="label">A LITTLE COLOR</span><h1>Make it yours.</h1><p>A calm surface and a clear hierarchy.</p></article>',css:base+'\n.color-card { padding: 2rem; border: 1px solid #d4dfc5; border-radius: 18px; background-color: #edf4df; background-image: linear-gradient(135deg, #edf4df, #f9f9e9); box-shadow: 0 8px 24px rgb(39 67 40 / 8%); }\n.label { color: #506535; font-size: .75rem; letter-spacing: .15em; }',sources:['https://www.w3.org/TR/css-color-4/','https://www.w3.org/TR/css-backgrounds-3/','https://www.w3.org/TR/css-images-3/']},
{id:'responsive',topic:'CSS',title:'Responsive design and media queries',summary:'Adapt layouts to the available space and user preferences.',meaning:'A media query conditionally applies styles based on media features such as viewport width or user preferences. Responsive design also uses intrinsically flexible layouts, responsive images, and fluid sizing. The viewport meta element helps mobile browsers use an appropriate layout viewport.',where:'Use responsive rules in any site expected to work on phones, tablets, desktop windows, or print. Choose breakpoints according to content needs rather than a single device model.',steps:['Start with a layout that works in a narrow viewport.','Use flexible dimensions, max-width constraints, and wrapping before adding many breakpoints.','Add @media conditions where the content benefits from a layout change.','Consider pointer/hover capabilities and preferences such as prefers-reduced-motion.','Test with long text, keyboard navigation, zoom, and both portrait and landscape orientations.'],pitfalls:['A responsive preview is an aid, not proof of compatibility with every browser or input device.','Avoid hiding essential content to make the page fit a smaller screen.'],html:'<main class="layout"><section><h1>A flexible little page.</h1><p>One column on small screens. Two when there is room.</p></section><aside>A supporting idea.</aside></main>',css:base+'\n.layout { display: grid; gap: 1rem; }\nsection, aside { padding: 1.5rem; background: #edf4df; border-radius: 12px; }\n@media (min-width: 700px) { .layout { grid-template-columns: 2fr 1fr; } }\n@media print { body { color: black; background: white; } }',sources:['https://www.w3.org/TR/mediaqueries-4/','https://www.w3.org/TR/mediaqueries-5/']},
{id:'container',topic:'CSS',title:'Container queries and reusable components',summary:'Respond to a component’s own space rather than only the viewport.',meaning:'Size container queries apply descendant styles according to an eligible ancestor query container’s size. container-type:inline-size enables inline-axis size queries. @container chooses conditions, and container-name can distinguish named query containers. This allows one component to adapt in a narrow sidebar and a wide main area on the same page.',where:'Use container queries in reusable cards, side panels, widgets, and component libraries where available space depends on the parent layout.',steps:['Choose an ancestor wrapper as the query container.','Set container-type:inline-size when querying its inline size.','Write an @container condition and place descendant rules inside it.','Keep a useful default layout outside the query for narrow containers and fallback environments.','Use container-query units only when their reference behavior is understood.'],pitfalls:['A size query generally styles descendants of the queried container, not the container itself based on its own size.','Containment can affect intrinsic sizing. Do not add it to every element without understanding the effect.'],html:'<div class="component-space"><article class="responsive-card"><h1>A good fit.</h1><p>This card adapts to its parent’s width.</p></article></div>',css:base+'\n.component-space { container-type: inline-size; }\n.responsive-card { padding: 1.5rem; background: #edf4df; border-radius: 12px; }\n@container (min-width: 500px) { .responsive-card { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; align-items: center; } }',sources:['https://www.w3.org/TR/css-contain-3/']},
{id:'variables',topic:'CSS',title:'Custom properties and reusable design values',summary:'Create themes and avoid scattering repeated values.',meaning:'A custom property is an author-defined property whose name begins with --. It participates in the cascade. var() substitutes its value and can provide a fallback when the referenced custom property is missing or invalid as a custom property. Unregistered custom properties normally inherit. @property can register syntax, inheritance behavior, and an initial value.',where:'Use custom properties for theme colors, spacing scales, component settings, and runtime-controlled design values. They remain CSS values and are not a general programming language.',steps:['Define common values on :root or a suitable component ancestor.','Reference a value using var(--name). Custom property names are case-sensitive.','Override a token on a subtree to create a component variation or theme.','Use a fallback, such as var(--accent, #456b35), where an undefined variable needs a default.','Check @property support before relying on registered syntax or animation behavior.'],pitfalls:['var() fallback does not rescue every invalid final declaration. A defined value can become invalid for the destination property after substitution.','Custom properties can carry arbitrary token sequences, but the property consuming them still has its own grammar.'],html:'<article class="theme-card"><h1>A shared language.</h1><p>One token can shape many components.</p><button type="button">Build something</button></article>',css:base+'\n:root { --accent: #456b35; --surface: #edf4df; --space: 1.5rem; }\n.theme-card { background: var(--surface); padding: var(--space); border-radius: 12px; }\nbutton { background: var(--accent, #34522b); color: white; border: 0; padding: .8rem 1.2rem; border-radius: 7px; }',sources:['https://www.w3.org/TR/css-variables-1/','https://www.w3.org/TR/css-properties-values-api-1/']},
{id:'motion',topic:'CSS',title:'Transitions, animations, and reduced motion',summary:'Explain a change without making the interface exhausting.',meaning:'A transition interpolates a property when its value changes. An animation uses named @keyframes and animation properties to control time, iteration, direction, and related behavior. transform changes an element’s coordinate system without changing its normal-flow placement. Not all properties animate in the same way.',where:'Use motion for useful feedback and continuity, such as a subtle interactive state. Provide a reduced-motion alternative for users who request it.',steps:['Choose a small set of properties rather than defaulting to transition:all.','Set a duration and easing function appropriate to the change.','Use @keyframes for a defined sequence rather than a single state change.','Prefer changes that do not unnecessarily trigger layout on every frame.','Use @media (prefers-reduced-motion:reduce) to reduce or disable nonessential movement.'],pitfalls:['A hover animation needs a keyboard-equivalent interaction state where appropriate.','Never make essential understanding depend only on motion or a rapid timed effect.'],html:'<button class="motion-button" type="button">A little lift ↗</button>',css:base+'\n.motion-button { padding: 1rem 1.4rem; background: #d8edba; border: 1px solid #c0d49f; border-radius: 9px; transition: transform 180ms ease, background-color 180ms ease; }\n.motion-button:is(:hover, :focus-visible) { transform: translateY(-3px); background-color: #c8e69f; }\n.motion-button:focus-visible { outline: 3px solid #78994e; outline-offset: 4px; }\n@media (prefers-reduced-motion: reduce) { .motion-button { transition: none; } .motion-button:is(:hover, :focus-visible) { transform: none; } }',sources:['https://www.w3.org/TR/css-transitions-1/','https://www.w3.org/TR/css-animations-1/','https://www.w3.org/TR/css-transforms-1/','https://www.w3.org/TR/mediaqueries-5/#prefers-reduced-motion']},
{id:'logical',topic:'CSS',title:'Logical properties and writing directions',summary:'Describe layout in terms of text flow.',meaning:'Logical properties use inline and block axes rather than assuming left/right and top/bottom relationships. The axes depend on writing-mode and direction. margin-inline, padding-block, inline-size, and border-inline-start can make components more adaptable to right-to-left and vertical writing.',where:'Use logical properties in internationalized interfaces, reusable component libraries, and any layout that should follow the document’s writing direction.',steps:['Use inline-size for the dimension along the inline axis and block-size for the block axis when that meaning is intended.','Use margin-inline:auto for symmetric inline-axis centering.','Use start/end values instead of left/right when alignment should follow text direction.','Set lang and, where needed, dir in HTML according to the content.','Test mixed-direction text and punctuation rather than only translating short labels.'],pitfalls:['Logical and physical properties can target the same edge. Avoid contradictory declarations unless their precedence is deliberate.','Text direction and language are related but are not interchangeable settings.'],html:'<article class="logical-card" dir="rtl"><h1 lang="ar">مرحبا بالعالم</h1><p>A component can follow its content’s writing direction.</p></article>',css:base+'\n.logical-card { max-inline-size: 30rem; margin-inline: auto; padding-block: 1.5rem; padding-inline: 2rem; border-inline-start: 5px solid #a1be75; background: #edf4df; text-align: start; }',sources:['https://www.w3.org/TR/css-logical-1/','https://www.w3.org/TR/css-writing-modes-4/']},
{id:'supports',topic:'CSS',title:'Feature queries, fallbacks, and experimental features',summary:'Separate specification status from browser support.',meaning:'A feature can be defined in a specification without being implemented in every browser. @supports conditionally applies rules according to whether a browser accepts a tested declaration or supported condition. Browser compatibility records include versions, flags, prefixes, partial implementations, and notes. These are more specific than a simple yes/no “modern CSS” claim.',where:'Use progressive enhancement for advanced layouts, selectors, color functions, and other features whose support differs among browsers.',steps:['Write a useful base experience first.','Add an @supports block around enhancements that depend on a feature.','Check the full compatibility notes for the feature, not only the first version number.','Treat experimental and draft entries as research material until your target browsers and requirements justify them.','Test the actual browser versions you support; a syntax check is not a complete behavioral test.'],pitfalls:['@supports can establish acceptance of a declaration, not that every rendering detail is correct.','A CSS Snapshot groups specifications by stability and is not a guarantee of implementation across browsers.'],html:'<div class="enhanced"><article>First idea</article><article>Next idea</article></div>',css:base+'\n.enhanced > article { margin-block: 1rem; padding: 1rem; background: #edf4df; }\n@supports (display: grid) { .enhanced { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; } .enhanced > article { margin: 0; } }',sources:['https://www.w3.org/TR/css-conditional-3/','https://www.w3.org/TR/css-2026/','https://github.com/mdn/browser-compat-data']},
{id:'accessibility',topic:'Workflow',title:'Accessibility, readable UI, and keyboard use',summary:'Make learning and interaction available to more people.',meaning:'Accessible interfaces provide meaningful structure, visible labels, keyboard access, understandable focus, readable text, and alternatives to sensory-only information. Native HTML controls supply many useful behaviors. ARIA can describe semantics and state where native semantics do not already fit, but it does not create keyboard behavior by itself.',where:'Apply accessibility throughout navigation, forms, dialogs, documentation, and games. Offer untimed solo practice when a timed game mode would prevent a learner from participating comfortably.',steps:['Start with native elements: button for actions, a for navigation, input/select/textarea for controls.','Keep visible focus indicators and a logical focus order.','Give fields visible labels and errors that explain how to recover.','Keep text readable, allow zoom, and check foreground/background contrast.','For custom dialogs, manage initial focus, keep focus within the modal, support dismissal, and restore focus when appropriate.'],pitfalls:['Adding role="button" to a div does not automatically give it button keyboard behavior.','Color alone should not communicate correct/incorrect answers. Use text and icons as well.'],html:'<form>\n  <label for="display-name">Display name</label>\n  <p id="name-help">Use 2–20 characters. This name is visible to your room.</p>\n  <input id="display-name" name="name" aria-describedby="name-help" minlength="2" maxlength="20" required>\n  <button type="submit">Join the learning room</button>\n</form>',css:base+'\ninput, button { display: block; padding: .9rem; margin-block: .75rem; font: inherit; max-width: 100%; }\n:focus-visible { outline: 3px solid #486f37; outline-offset: 4px; }\n#name-help { color: #586c50; }',sources:['https://www.w3.org/WAI/tutorials/','https://www.w3.org/TR/WCAG22/','https://html.spec.whatwg.org/multipage/interaction.html']},
{id:'hosting',topic:'Workflow',title:'From a local page to GitHub Pages',summary:'Understand static hosting, file paths, and the multiplayer connection.',meaning:'GitHub Pages publishes static HTML, CSS, JavaScript, and assets. It does not run the multiplayer game server. The exported Markup frontend therefore calls a separately hosted API for shared rooms. Solo practice, documentation, and the playground run in the browser; multiplayer requires an internet connection and an available backend.',where:'Use the supplied Pages build in a public GitHub repository for GitHub Free hosting. Use the provided workflow or publish the generated static directory with a branch source.',steps:['Build the Pages frontend using the supplied pages build command. The output has index.html and relative asset URLs.','Keep secret credentials out of frontend code and the repository. A backend origin is public configuration, not a secret.','Enable GitHub Pages for the new repository and choose GitHub Actions as the deployment source when using the supplied workflow.','Make sure the backend permits the exact Pages origin through its access policy and CORS rules.','Verify both the published frontend and an actual two-player room across hosts before calling the deployment complete.'],pitfalls:['Uploading only a server-rendered framework source tree does not turn it into a functioning static website.','A private backend or missing cross-origin headers will prevent public Pages visitors from using online rooms.','A successful local test is not proof that a GitHub Pages deployment has finished.'],html:'<main><h1>Ready for the web.</h1><p>Static content is served by GitHub Pages. Shared game state lives in the hosted multiplayer API.</p></main>',css:base+'\nmain { max-width: 40rem; padding: 2rem; border: 1px solid #d3dfc5; border-radius: 12px; background: #edf4df; }',sources:['https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages','https://docs.github.com/en/pages/getting-started-with-github-pages/creating-a-github-pages-site','https://developers.cloudflare.com/workers/examples/cors-header-proxy/']},
...moreGuides,...deepGuides
];
